
jQuery( document ).ready( function ( $ ) {
	var file_frame;
	var $settings_wrapper;

	var get_media_field = function ( self, settings_wrapper, element_id ) {
		var $input = $( '#woi-pdf-settings' ).find( element_id ).filter( function () {
			var parent = self.parent( 'div' );
			return parent.length && parent.attr( 'aria-hidden' ) === 'false';
		} );
		return $input.length ? $input : settings_wrapper.find( element_id );
	};

	$( '#woi-pdf-settings, .woi-pdf-setup' ).on( 'click', '.wpo_upload_image_button', function ( event ) {
		event.preventDefault();
		$settings_wrapper = $( this ).parent();

		if ( file_frame ) {
			file_frame.open();
			return;
		}

		file_frame = wp.media.frames.file_frame = wp.media( {
			title:    $( this ).data( 'uploader_title' ),
			button:   { text: $( this ).data( 'uploader_button_text' ) },
			multiple: false,
		} );

		file_frame.on( 'select', function () {
			var $input   = get_media_field( $( this ), $settings_wrapper, 'input.media-upload-id' );
			var $preview = get_media_field( $( this ), $settings_wrapper, 'img.media-upload-preview' );
			var attachment = file_frame.state().get( 'selection' ).first().toJSON();

			$input.val( attachment.id );
			if ( $preview.length ) {
				$preview.attr( 'src', attachment.url );
			}

			get_media_field( $( this ), $settings_wrapper, '.attachment-resolution, .attachment-resolution-warning' ).remove();

			$settings_wrapper.parent().block( {
				message: null,
				overlayCSS: { background: '#fff', opacity: 0.6 },
			} );

			$.ajax( {
				type:    'POST',
				url:     woi_pdf_admin.ajaxurl,
				data: {
					security:      $input.data( 'ajax_nonce' ),
					action:        'woi_pdf_get_media_upload_setting_html',
					args:          $input.data( 'settings_callback_args' ),
					attachment_id: attachment.id,
				},
				success: function ( response ) {
					if ( response && typeof response.success !== 'undefined' && response.success === true ) {
						$settings_wrapper.html( response.data );
					}
					$settings_wrapper.removeAttr( 'style' );
					$settings_wrapper.parent().unblock();
					$input = get_media_field( $( this ), $settings_wrapper, 'input.media-upload-id' );
					$( document.body ).trigger( 'woi-pdf-media-upload-setting-updated', [ $input ] );
				},
				error: function () {
					$settings_wrapper.parent().unblock();
				},
			} );
		} );

		file_frame.open();
	} );

	$( '#woi-pdf-settings, .woi-pdf-setup' ).on( 'click', '.wpo_remove_image_button', function ( event ) {
		var $sw     = $( this ).parent();
		var $input  = $sw.find( 'input.media-upload-id' );
		var $preview = $sw.find( 'img.media-upload-preview' );
		$input.val( '' );
		$preview.remove();
		$( this ).remove();
		get_media_field( $( this ), $sw, '.attachment-resolution, .attachment-resolution-warning' ).remove();
	} );
} );
